"""Independent slow-but-sure oracle: dict states, no pruning, no codegen.

Used to double check answers on instances too big for permutation brute force.
Re-implements the reference op semantics directly on dicts.
"""
import sys


def apply_ops(ops, d):
    """Apply one transaction's ops to dict d; return new dict or None."""
    d = dict(d)
    for op in ops:
        k = op[0]
        if k == "get":
            if d.get(op[1]) != op[2]:
                return None
        elif k == "put":
            d[op[1]] = op[2]
        elif k == "del":
            d.pop(op[1], None)
        elif k == "cas":
            _, key, old, new, want = op
            ok = d.get(key) == old
            if ok is not want:
                return None
            if ok:
                if new is None:
                    d.pop(key, None)
                else:
                    d[key] = new
        else:
            if sorted([[x, v] for x, v in d.items() if op[1] <= x < op[2]]) != op[3]:
