def _freeze(v):
    """Hashable, ==-compatible key for a JSON value (lists/dicts included)."""
    t = type(v)
    if t is list:
        return ("L",) + tuple(_freeze(x) for x in v)
    if t is dict:
        return ("D",) + tuple(sorted((_freeze(k), _freeze(x)) for k, x in v.items()))
    return v


def _unhashable(v):
    try:
